-- -------------------------------------------------------------
-- Struktur Tabel: `benefits`
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `benefits`;
CREATE TABLE `benefits` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Judul benefit',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT 'Penjelasan benefit',
  `icon` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Nama/class icon',
  `image` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Path/URL gambar ilustrasi',
  `sort_order` int(11) NOT NULL DEFAULT '0' COMMENT 'Urutan tampil (ascending)',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1 = aktif, 0 = nonaktif',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_benefits_status` (`status`),
  KEY `idx_benefits_sort_order` (`sort_order`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Manfaat dan fasilitas perusahaan (Benefits & Perks)';

-- Data untuk Tabel: `benefits` (4 baris)
INSERT INTO `benefits` (`id`, `title`, `description`, `icon`, `image`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES (1, 'Asuransi & Jaminan Kesehatan', 'BPJS Kesehatan & Ketenagakerjaan lengkap ditambah asuransi swasta rawat inap karyawan dan keluarga.', 'shield', NULL, 10, 1, '2026-10-01 02:49:22', '2026-10-01 02:49:22');
INSERT INTO `benefits` (`id`, `title`, `description`, `icon`, `image`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES (2, 'Sertifikasi IPC & IATF Berbayar', 'Pelatihan resmi dan sertifikasi IPC-A-610 serta metodologi Six Sigma dibiayai penuh oleh perusahaan.', 'award', NULL, 20, 1, '2026-10-01 02:49:22', '2026-10-01 02:49:22');
INSERT INTO `benefits` (`id`, `title`, `description`, `icon`, `image`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES (3, 'Fasilitas Modern ESD Cleanroom', 'Lingkungan kerja ber-AC dengan regulasi suhu dan proteksi ESD ISO Class 8 berstandar otomotif internasional.', 'cpu', NULL, 30, 1, '2026-10-01 02:49:22', '2026-10-01 02:49:22');
INSERT INTO `benefits` (`id`, `title`, `description`, `icon`, `image`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES (4, 'Program Magang Bersertifikat', 'Uang saku bulanan, bimbingan langsung engineer senior, dan jalur prioritas rekrutmen karyawan tetap.', 'graduation-cap', NULL, 40, 1, '2026-10-01 02:49:22', '2026-10-01 02:49:22');

-- -------------------------------------------------------------
-- Struktur Tabel: `company_profile`
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `company_profile`;
CREATE TABLE `company_profile` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Nama/judul profil perusahaan',
  `title_en` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` text COLLATE utf8mb4_unicode_ci COMMENT 'Deskripsi singkat perusahaan',
  `description_en` text COLLATE utf8mb4_unicode_ci,
  `vision` text COLLATE utf8mb4_unicode_ci COMMENT 'Visi perusahaan',
  `vision_en` text COLLATE utf8mb4_unicode_ci,
  `mission` text COLLATE utf8mb4_unicode_ci COMMENT 'Misi perusahaan',
  `mission_en` text COLLATE utf8mb4_unicode_ci,
  `about_image` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Path/URL foto profil perusahaan',
  `updated_by` int(11) DEFAULT NULL COMMENT 'FK: ID user yang terakhir update',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `fk_company_profile_users` (`updated_by`),
  CONSTRAINT `fk_company_profile_users` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Profil, visi, dan misi perusahaan (singleton)';

-- Data untuk Tabel: `company_profile` (1 baris)
INSERT INTO `company_profile` (`id`, `title`, `title_en`, `description`, `description_en`, `vision`, `vision_en`, `mission`, `mission_en`, `about_image`, `updated_by`, `created_at`, `updated_at`) VALUES (1, 'PT. Global Philsonic Technologies', 'PT. Global Philsonic Technologies', 'PT. Global Philsonic Technologies (GPT) adalah manufaktur perakitan elektronik presisi tinggi dan solusi otomasi industri terdepan yang beroperasi di Kawasan Bebas Batam (Free Trade Zone). Dengan fasilitas seluas 10.000 mt berstandar IATF 16949, kami memproduksi modul elektronik otomotif, headunit QLED pintar, sistem prosesor audio DSP, perangkat sensor keselamatan berkendara, dan jig uji fungsional otomatis berkecepatan 80.000 CPH.', 'PT. Global Philsonic Technologies (GPT) is a leading manufacturer of high-precision electronic assembly and industrial automation solutions operating in the Batam Free Zone (Free Trade Zone). With a 10,000 mt facility with IATF 16949 standards, we produce automotive electronic modules, smart QLED headunits, DSP audio processor systems, driving safety sensor devices and automatic functional test jigs at 80,000 CPH.', 'Menjadi mitra manufaktur Tier-1 elektronik otomotif dan rekayasa otomasi terpercaya di Asia Tenggara dengan standar mutu nol-cacat (Zero-Defect) serta efisiensi logistik bebas bea global.', 'Become a trusted Tier-1 manufacturing partner for automotive electronics and automation engineering in Southeast Asia with zero-defect quality standards and global duty-free logistics efficiency.', 'Menghasilkan perakitan SMT presisi tinggi dengan toleransi mikron sesuai standar otomotif internasional IATF 16949.\nMemberikan layanan OEM/ODM terintegrasi mulai dari DFM, prototyping kilat, hingga produksi massal dan box-build turnkey.\nMengembangkan solusi rekayasa otomasi dan mesin jig uji pintar untuk memaksimalkan yield industri 4.0.', 'Produces high precision SMT assemblies with micron tolerances to international automotive standard IATF 16949.\nProviding integrated OEM/ODM services from DFM, flash prototyping, to mass production and turnkey box-build.\nDevelop automation engineering solutions and smart test jig machines to maximize industry 4.0 yields.', '/images/hero-smt.jpg', 1, '2026-10-01 02:49:21', '2026-10-12 03:45:21');

-- -------------------------------------------------------------
-- Struktur Tabel: `contact_recruitment`
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `contact_recruitment`;
CREATE TABLE `contact_recruitment` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `email` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Email tim rekrutmen',
  `phone` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Nomor telepon/HP',
  `address` text COLLATE utf8mb4_unicode_ci COMMENT 'Alamat lengkap kantor',
  `address_en` text COLLATE utf8mb4_unicode_ci,
  `instagram` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'URL/username Instagram',
  `linkedin` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'URL LinkedIn perusahaan',
  `whatsapp` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Nomor WhatsApp rekrutmen',
  `updated_by` int(11) DEFAULT NULL COMMENT 'FK: ID user yang terakhir update',
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `maps_latitude` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT '1.1368003',
  `maps_longitude` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT '104.0452514',
  `maps_place_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT 'GLOBAL PHILSONIC TECHNOLOGIES',
  `maps_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT 'https://www.google.com/maps/place/GLOBAL+PHILSONIC+TECHNOLOGIES/@1.137263,104.045233,435m/data=!3m1!1e3!4m6!3m5!1s0x31d98900364038b5:0xf424af624a151322!8m2!3d1.1368003!4d104.0452514!16s%2Fg%2F11z007pkw1?hl=id',
  `maps_embed_url` text COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`),
  KEY `fk_contact_recruitment_users` (`updated_by`),
  CONSTRAINT `fk_contact_recruitment_users` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Informasi kontak tim rekrutmen (singleton)';

-- Data untuk Tabel: `contact_recruitment` (1 baris)
INSERT INTO `contact_recruitment` (`id`, `email`, `phone`, `address`, `address_en`, `instagram`, `linkedin`, `whatsapp`, `updated_by`, `updated_at`, `maps_latitude`, `maps_longitude`, `maps_place_name`, `maps_url`, `maps_embed_url`) VALUES (1, 'contact@philsonic.co.id', '+62 778 480 8888', 'Cammo Industrial Park Blok B No. 8-10, Batam Center, Batam, Kepulauan Riau 29461 (Batam FTZ)', 'Batam Industrial Park, Mukakuning, Batam Free Trade Zone, Riau Islands 29433, Indonesia', 'https://instagram.com/philsonic.technologies', 'https://linkedin.com/company/pt-global-philsonic-technologies', '+62 811 7700 888', 1, '2026-10-01 03:22:55', '1.1368003', '104.0452514', 'GLOBAL PHILSONIC TECHNOLOGIES', 'https://www.google.com/maps/place/GLOBAL+PHILSONIC+TECHNOLOGIES/@1.137263,104.045233,435m/data=!3m1!1e3!4m6!3m5!1s0x31d98900364038b5:0xf424af624a151322!8m2!3d1.1368003!4d104.0452514!16s%2Fg%2F11z007pkw1?hl=id', 'https://maps.google.com/maps?q=1.1368003,104.0452514+(GLOBAL%20PHILSONIC%20TECHNOLOGIES)&t=m&z=17&ie=UTF8&iwloc=B&output=embed');

-- -------------------------------------------------------------
-- Struktur Tabel: `core_values`
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `core_values`;
CREATE TABLE `core_values` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Judul/nama core value',
  `title_en` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` text COLLATE utf8mb4_unicode_ci COMMENT 'Penjelasan core value',
  `description_en` text COLLATE utf8mb4_unicode_ci,
  `icon` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Nama icon (misal: class icon atau path file)',
  `sort_order` int(11) NOT NULL DEFAULT '0' COMMENT 'Urutan tampil (ascending)',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1 = aktif, 0 = nonaktif',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_core_values_status` (`status`),
  KEY `idx_core_values_sort_order` (`sort_order`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Nilai-nilai utama (core values) perusahaan';

-- Data untuk Tabel: `core_values` (6 baris)
INSERT INTO `core_values` (`id`, `title`, `title_en`, `description`, `description_en`, `icon`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES (1, 'Zero-Defect Quality Culture', 'Zero-Defect Quality Culture', 'Kepatuhan mutlak standar otomotif IATF 16949 & ISO 9001:2015 dengan inspeksi 100% 3D SPI, inline AOI, dan audit X-Ray.', 'Kepatuhan mutlak standar otomotif IATF 16949 & ISO 9001:2015 dengan inspeksi 100% 3D SPI, inline AOI, dan audit X-Ray.', 'award', 10, 1, '2026-10-01 02:49:21', '2026-10-01 03:22:55');
INSERT INTO `core_values` (`id`, `title`, `title_en`, `description`, `description_en`, `icon`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES (2, 'Precision SMT Placement', 'Precision SMT Placement', 'Penempatan komponen pasif ukuran 0201 dan BGA fine-pitch berkecepatan 80.000 CPH dengan akurasi mikron tinggi.', 'Penempatan komponen pasif ukuran 0201 dan BGA fine-pitch berkecepatan 80.000 CPH dengan akurasi mikron tinggi.', 'cpu', 20, 1, '2026-10-01 02:49:21', '2026-10-01 03:22:55');
INSERT INTO `core_values` (`id`, `title`, `title_en`, `description`, `description_en`, `icon`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES (3, 'Turnkey OEM & ODM Co-Development', 'Turnkey OEM & ODM Co-Development', 'Dukungan penuh dari review DFM, prototyping kilat, fabrikasi stensil laser, hingga perakitan box-build siap pasar.', 'Dukungan penuh dari review DFM, prototyping kilat, fabrikasi stensil laser, hingga perakitan box-build siap pasar.', 'settings', 30, 1, '2026-10-01 02:49:21', '2026-10-01 03:22:55');
INSERT INTO `core_values` (`id`, `title`, `title_en`, `description`, `description_en`, `icon`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES (4, 'MES Barcode Traceability', 'MES Barcode Traceability', 'Pelacakan digital end-to-end setiap komponen dan lot PCB dari gudang komponen hingga pengiriman produk jadi.', 'Pelacakan digital end-to-end setiap komponen dan lot PCB dari gudang komponen hingga pengiriman produk jadi.', 'scan', 40, 1, '2026-10-01 02:49:21', '2026-10-01 03:22:55');
INSERT INTO `core_values` (`id`, `title`, `title_en`, `description`, `description_en`, `icon`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES (5, 'In-House Automation Workshop', 'In-House Automation Workshop', 'Fabrikasi mandiri jig mekanik CNC, ruang vakum pneumatik, dan fixture uji fungsional ICT/FCT.', 'Fabrikasi mandiri jig mekanik CNC, ruang vakum pneumatik, dan fixture uji fungsional ICT/FCT.', 'wrench', 50, 1, '2026-10-01 02:49:21', '2026-10-01 03:22:55');
INSERT INTO `core_values` (`id`, `title`, `title_en`, `description`, `description_en`, `icon`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES (6, 'Batam FTZ Strategic Logistics', 'Batam FTZ Strategic Logistics', 'Fasilitas kawasan bebas bea di Batam dengan rute feri kargo 45 menit langsung ke pelabuhan internasional Singapura.', 'Fasilitas kawasan bebas bea di Batam dengan rute feri kargo 45 menit langsung ke pelabuhan internasional Singapura.', 'truck', 60, 1, '2026-10-01 02:49:21', '2026-10-01 03:22:55');

-- -------------------------------------------------------------
-- Struktur Tabel: `faqs`
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `faqs`;
CREATE TABLE `faqs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `question` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Pertanyaan yang sering ditanyakan',
  `answer` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Jawaban atas pertanyaan',
  `sort_order` int(11) NOT NULL DEFAULT '0' COMMENT 'Urutan tampil (ascending)',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1 = aktif, 0 = nonaktif',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_faqs_status` (`status`),
  KEY `idx_faqs_sort_order` (`sort_order`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='FAQ seputar proses rekrutmen dan seleksi';

-- Data untuk Tabel: `faqs` (4 baris)
INSERT INTO `faqs` (`id`, `question`, `answer`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES (1, 'Apa keunggulan memproduksi elektronik otomotif di Batam Free Trade Zone (FTZ)?', 'Batam Free Trade Zone memberikan fasilitas 0% bea masuk untuk impor bahan baku dan komponen elektronik, pembebasan PPN/PPnBM, serta efisiensi waktu logistik laut hanya 45 menit menuju pelabuhan internasional Singapura.', 1, 1, '2026-10-01 02:49:22', '2026-10-05 02:29:37');
INSERT INTO `faqs` (`id`, `question`, `answer`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES (2, 'Apakah PT. Global Philsonic Technologies melayani pesanan kustom OEM dan ODM?', 'Ya, kami menyediakan layanan OEM/ODM lengkap, mulai dari perancangan skematik PCB, peninjauan DFM, prototipe cepat 10-50 unit, pembuatan tooling stensil laser, hingga perakitan massal berkecepatan 80.000 CPH dan box-build turnkey.', 2, 1, '2026-10-01 02:49:22', '2026-10-05 02:29:41');
INSERT INTO `faqs` (`id`, `question`, `answer`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES (3, 'Sertifikasi mutu apa saja yang dimiliki oleh pabrik GPT?', 'Pabrik kami beroperasi penuh dengan sertifikasi otomotif IATF 16949:2016, sistem manajemen mutu ISO 9001:2015, dan kepatuhan operator berstandar IPC-A-610 Class 3.', 3, 1, '2026-10-01 02:49:22', '2026-10-05 02:29:51');
INSERT INTO `faqs` (`id`, `question`, `answer`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES (4, 'Bagaimana proses pengajuan penawaran resmi (RFQ) untuk proyek perakitan?', 'Anda dapat menghubungi tim sales engineering kami melalui formulir kontak atau tombol WhatsApp B2B di halaman Produk dengan melampirkan file Gerber, Bill of Materials (BOM), dan estimasi volume kebutuhan.', 4, 1, '2026-10-01 02:49:22', '2026-10-05 02:29:56');

-- -------------------------------------------------------------
-- Struktur Tabel: `gallery`
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `gallery`;
CREATE TABLE `gallery` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Judul foto/kegiatan',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT 'Deskripsi foto/kegiatan',
  `image` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Path/URL gambar',
  `category` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Kategori kegiatan (misal: team building, workshop)',
  `event_date` date DEFAULT NULL COMMENT 'Tanggal kegiatan berlangsung',
  `status` enum('active','inactive') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active' COMMENT 'Status tampil di publik',
  `created_by` int(11) DEFAULT NULL COMMENT 'FK: ID user yang upload',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_gallery_status` (`status`),
  KEY `idx_gallery_category` (`category`),
  KEY `fk_gallery_users` (`created_by`),
  CONSTRAINT `fk_gallery_users` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Galeri foto kegiatan perusahaan (Life at ISA)';

-- Data untuk Tabel: `gallery` (8 baris)
INSERT INTO `gallery` (`id`, `title`, `description`, `image`, `category`, `event_date`, `status`, `created_by`, `created_at`, `updated_at`) VALUES (1, 'High-Speed SMT Modular Placement Lines', 'High-precision dual-beam Yamaha YSM20R mounters capable of 80,000 CPH, placing 0201 passives, fine-pitch BGA, and automotive microcontrollers.', 'https://images.unsplash.com/photo-1581092160607-ee22621dd758?auto=format&fit=crop&w=1000&q=80', 'SMT Lines', '2026-02-14 17:00:00', 'active', 1, '2026-10-01 02:49:21', '2026-10-01 02:49:21');
INSERT INTO `gallery` (`id`, `title`, `description`, `image`, `category`, `event_date`, `status`, `created_by`, `created_at`, `updated_at`) VALUES (2, '10-Zone Nitrogen Convection Reflow Oven', 'Automotive grade reflow soldering with real-time KIC thermal profiling, O2 ppm control (<100 ppm), ensuring zero-voiding on critical power electronics.', 'https://images.unsplash.com/photo-1581092335397-9583fe92d232?auto=format&fit=crop&w=1000&q=80', 'SMT Lines', '2026-02-28 17:00:00', 'active', 1, '2026-10-01 02:49:21', '2026-10-01 02:49:21');
INSERT INTO `gallery` (`id`, `title`, `description`, `image`, `category`, `event_date`, `status`, `created_by`, `created_at`, `updated_at`) VALUES (3, 'ISO Class 8 (100K) Static-Controlled Cleanroom', 'Dedicated dust-free environment with continuous ESD floor grounding, positive air pressure, HEPA filtration, and strict temperature stability.', 'https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?auto=format&fit=crop&w=1000&q=80', 'Cleanroom Class 100K', '2026-03-09 17:00:00', 'active', 1, '2026-10-01 02:49:21', '2026-10-01 02:49:21');
INSERT INTO `gallery` (`id`, `title`, `description`, `image`, `category`, `event_date`, `status`, `created_by`, `created_at`, `updated_at`) VALUES (4, '3D Solder Paste Inspection (SPI) & 3D AOI Station', 'Inline 3D moire fringe metrology measuring solder volume, height, and offset down to micron level before reflow.', 'https://images.unsplash.com/photo-1581092580497-e0d23cbdf1dc?auto=format&fit=crop&w=1000&q=80', 'QA & Lab Testing', '2026-03-17 17:00:00', 'active', 1, '2026-10-01 02:49:21', '2026-10-01 02:49:21');
INSERT INTO `gallery` (`id`, `title`, `description`, `image`, `category`, `event_date`, `status`, `created_by`, `created_at`, `updated_at`) VALUES (5, 'In-House CNC Mechanical Tooling & Jig Fabrication', 'Haas 4-axis machining centers and precision drill presses crafting custom ESD-safe Bakelite and POM-C test fixtures.', 'https://images.unsplash.com/photo-1581092795360-fd1ca04f0952?auto=format&fit=crop&w=1000&q=80', 'Workshop Otomasi', '2026-04-04 17:00:00', 'active', 1, '2026-10-01 02:49:21', '2026-10-01 02:49:21');
INSERT INTO `gallery` (`id`, `title`, `description`, `image`, `category`, `event_date`, `status`, `created_by`, `created_at`, `updated_at`) VALUES (6, 'High-Resolution 2D/3D X-Ray Non-Destructive Inspection', '160 kV microfocus open-tube X-ray inspection for detecting solder voids under BGA balls, QFN pads, and wire bond integrity.', 'https://images.unsplash.com/photo-1581092162384-8987c1d64718?auto=format&fit=crop&w=1000&q=80', 'QA & Lab Testing', '2026-04-11 17:00:00', 'active', 1, '2026-10-01 02:49:21', '2026-10-01 02:49:21');
INSERT INTO `gallery` (`id`, `title`, `description`, `image`, `category`, `event_date`, `status`, `created_by`, `created_at`, `updated_at`) VALUES (7, 'Environmental Thermal Shock & Burn-In Chamber', 'Rapid temperature cycling from -40┬░C to +125┬░C under continuous operational electrical load to stress-test solder joint durability.', 'https://images.unsplash.com/photo-1581094794329-c8112a89af12?auto=format&fit=crop&w=1000&q=80', 'QA & Lab Testing', '2026-05-01 17:00:00', 'active', 1, '2026-10-01 02:49:21', '2026-10-01 02:49:21');
INSERT INTO `gallery` (`id`, `title`, `description`, `image`, `category`, `event_date`, `status`, `created_by`, `created_at`, `updated_at`) VALUES (8, 'Batam Free Trade Zone Plant & Bonded Logistics Staging', 'Strategic 10,000 m┬▓ manufacturing hub situated 45 minutes by fast sea freight from Singapore port, featuring bonded customs clearance.', 'https://images.unsplash.com/photo-1586528116311-ad8dd3c8310d?auto=format&fit=crop&w=1000&q=80', 'Gedung & Logistik', '2026-05-19 17:00:00', 'active', 1, '2026-10-01 02:49:21', '2026-10-01 02:49:21');

-- -------------------------------------------------------------
-- Struktur Tabel: `job_categories`
