-- -------------------------------------------------------------
-- Struktur Tabel: `job_vacancies`
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `job_vacancies`;
CREATE TABLE `job_vacancies` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `category_id` int(11) NOT NULL COMMENT 'FK: Kategori/divisi lowongan',
  `title` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Judul posisi/jabatan',
  `title_en` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `location` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Lokasi penempatan (misal: Jakarta, Remote)',
  `employment_type` enum('Full Time','Part Time','Internship','Contract','OJT') COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Tipe pekerjaan',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT 'Deskripsi pekerjaan (job description)',
  `description_en` text COLLATE utf8mb4_unicode_ci,
  `responsibilities` text COLLATE utf8mb4_unicode_ci COMMENT 'Tanggung jawab pekerjaan',
  `responsibilities_en` text COLLATE utf8mb4_unicode_ci,
  `requirements` text COLLATE utf8mb4_unicode_ci COMMENT 'Persyaratan/kualifikasi pelamar',
  `requirements_en` text COLLATE utf8mb4_unicode_ci,
  `form_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'URL Google Form untuk Apply Now',
  `status` enum('draft','published','closed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft' COMMENT 'draft=belum publish, published=live, closed=ditutup',
  `published_at` timestamp NULL DEFAULT NULL COMMENT 'Waktu lowongan dipublikasikan',
  `closed_at` timestamp NULL DEFAULT NULL COMMENT 'Waktu lowongan ditutup',
  `created_by` int(11) DEFAULT NULL COMMENT 'FK: ID user yang membuat lowongan',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_job_vacancies_status` (`status`),
  KEY `idx_job_vacancies_category_id` (`category_id`),
  KEY `idx_job_vacancies_employment_type` (`employment_type`),
  KEY `idx_job_vacancies_location` (`location`),
  KEY `fk_job_vacancies_users` (`created_by`),
  CONSTRAINT `fk_job_vacancies_category` FOREIGN KEY (`category_id`) REFERENCES `job_categories` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `fk_job_vacancies_users` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Data lowongan kerja (Apply Now -> Google Form)';

-- Data untuk Tabel: `job_vacancies` (6 baris)
INSERT INTO `job_vacancies` (`id`, `category_id`, `title`, `title_en`, `location`, `employment_type`, `description`, `description_en`, `responsibilities`, `responsibilities_en`, `requirements`, `requirements_en`, `form_url`, `status`, `published_at`, `closed_at`, `created_by`, `created_at`, `updated_at`) VALUES (1, 1, 'Senior SMT Process Engineer', NULL, 'Batam FTZ Plant', 'Full Time', 'Lead solder paste printing optimization, reflow profile validation, and Yamaha YSM20R feeder setup to achieve zero-defect yields under IATF 16949 automotive standards.', NULL, 'Melakukan kalkulasi DFM & optimasi stencil printing\nMengatur profil suhu reflow nitrogen 10-zone\nMenangani root-cause analysis cacat SPI dan AOI 3D', NULL, 'S1 Teknik Elektro, Elektronika, atau Mekatronika\nPengalaman minimal 3 tahun di lini perakitan SMT kecepatan tinggi\nMemahami standar IPC-A-610 Class 3 & IATF 16949', NULL, 'https://forms.gle/ZEcDw4bXxtQw4iTw9', 'published', '2026-10-01 02:49:21', NULL, 1, '2026-10-01 02:49:21', '2026-10-01 09:44:27');
INSERT INTO `job_vacancies` (`id`, `category_id`, `title`, `title_en`, `location`, `employment_type`, `description`, `description_en`, `responsibilities`, `responsibilities_en`, `requirements`, `requirements_en`, `form_url`, `status`, `published_at`, `closed_at`, `created_by`, `created_at`, `updated_at`) VALUES (2, 2, 'Test Automation & PLC Programmer', NULL, 'Batam FTZ Plant', 'Full Time', 'Design, write firmware, and debug custom pneumatic test fixtures and functional test beds using Omron Sysmac, Mitsubishi PLC, and Python/LabVIEW instrumentation.', NULL, 'Merancang ladder logic PLC & sistem akuisisi data sensor\nMembangun fixture uji pneumatik kustom dengan katup Festo/SMC\nMengintegrasikan protokol CAN, LIN, dan RS485 pada jig ICT', NULL, 'D3/S1 Mekatronika, Otomasi, atau Teknik Komputer\nPengalaman pemrograman PLC & pengujian kelistrikan otomotif\nMampu membaca skematik pneumatik dan mekanik 2D/3D', NULL, 'https://forms.gle/ZEcDw4bXxtQw4iTw9', 'published', '2026-10-01 02:49:21', NULL, 1, '2026-10-01 02:49:21', '2026-10-01 09:44:23');
INSERT INTO `job_vacancies` (`id`, `category_id`, `title`, `title_en`, `location`, `employment_type`, `description`, `description_en`, `responsibilities`, `responsibilities_en`, `requirements`, `requirements_en`, `form_url`, `status`, `published_at`, `closed_at`, `created_by`, `created_at`, `updated_at`) VALUES (3, 3, 'QA Engineer - Automotive', NULL, 'Batam FTZ Plant', 'Full Time', 'Oversee incoming, in-process, and outgoing PCBA quality gate inspections, X-ray BGA analysis, and manage non-conformance 8D corrective action reports for OEM clients.', NULL, 'Memimpin inspeksi gerbang mutu SMT (SPI, AOI, X-Ray)\nMenyusun laporan korektif 8D untuk pelanggan Tier-1 internasional\nMengawal audit berkala ISO 9001 & IATF 16949', NULL, 'D3/S1 Teknik Industri atau Manajemen Mutu\nSertifikasi IPC-A-610 Specialist diutamakan\nKemampuan bahasa Inggris tertulis & lisan aktif', NULL, 'https://forms.gle/ZEcDw4bXxtQw4iTw9', 'published', '2026-10-01 02:49:21', NULL, 1, '2026-10-01 02:49:21', '2026-10-01 09:44:43');
INSERT INTO `job_vacancies` (`id`, `category_id`, `title`, `title_en`, `location`, `employment_type`, `description`, `description_en`, `responsibilities`, `responsibilities_en`, `requirements`, `requirements_en`, `form_url`, `status`, `published_at`, `closed_at`, `created_by`, `created_at`, `updated_at`) VALUES (4, 4, 'SMT Production Shift Supervisor', NULL, 'Batam FTZ Plant', 'Full Time', 'Direct shift line operators, coordinate line changeovers, enforce 5S cleanroom disciplines, and ensure daily manufacturing targets and OEE KPIs are surpassed.', NULL, 'Mengkoordinasikan pergantian setup lini perakitan komponen\nMemastikan penegakan disiplin ESD dan 5S cleanroom\nMencapai target OEE dan target output produksi harian', NULL, 'Pengalaman minimal 3 tahun sebagai supervisor di industri PCBA\nKepemimpinan kuat & siap bekerja dalam sistem shift Batam', NULL, 'https://forms.gle/ZEcDw4bXxtQw4iTw9', 'published', '2026-10-01 02:49:21', NULL, 1, '2026-10-01 02:49:21', '2026-10-01 09:44:14');
INSERT INTO `job_vacancies` (`id`, `category_id`, `title`, `title_en`, `location`, `employment_type`, `description`, `description_en`, `responsibilities`, `responsibilities_en`, `requirements`, `requirements_en`, `form_url`, `status`, `published_at`, `closed_at`, `created_by`, `created_at`, `updated_at`) VALUES (5, 2, 'CNC Tooling & Fixture Technician', NULL, 'Batam FTZ Plant', 'Full Time', 'Operate Haas 4-axis CNC milling centers to fabricate custom Bakelite and POM-C test nests, perform preventative maintenance on pneumatic actuators and probe pins.', NULL, 'Mengoperasikan mesin CNC Haas untuk pemotongan Bakelite ESD\nMelakukan kalibrasi jarum uji kelistrikan (ICT probe pins)\nMerawat aktuator pneumatik dan nesting mekanik', NULL, 'SMK Mesin atau D3 Teknik Mesin / Perkakas Presisi\nMampu membaca gambar teknik CAD (SolidWorks/AutoCAD)', NULL, 'https://forms.gle/ZEcDw4bXxtQw4iTw9', 'published', '2026-10-01 02:49:21', NULL, 1, '2026-10-01 02:49:21', '2026-10-01 09:44:19');
INSERT INTO `job_vacancies` (`id`, `category_id`, `title`, `title_en`, `location`, `employment_type`, `description`, `description_en`, `responsibilities`, `responsibilities_en`, `requirements`, `requirements_en`, `form_url`, `status`, `published_at`, `closed_at`, `created_by`, `created_at`, `updated_at`) VALUES (6, 5, 'Engineering & IoT Smart Factory Internship (6 Bulan)', NULL, 'Batam FTZ Plant', 'Internship', 'Program magang terstruktur 6 bulan untuk mahasiswa Politeknik / Universitas dalam bidang SMT Process, MES Industry 4.0 Telemetry, atau Embedded Firmware Testing.', NULL, 'Membantu engineer senior dalam pengujian jalur PCBA\nMenganalisis data telemetri MES dan efisiensi lini SMT\nTerlibat langsung dalam proyek otomatisasi industri', NULL, 'Mahasiswa aktif semester 5-8 Teknik Elektro, Mesin, atau Informatika\nDiberikan uang saku bulanan, sertifikat, dan peluang kerja tetap', NULL, 'https://forms.gle/ZEcDw4bXxtQw4iTw9', 'published', '2026-10-01 02:49:21', NULL, 1, '2026-10-01 02:49:21', '2026-10-01 09:42:45');

