-- -------------------------------------------------------------
-- Struktur Tabel: `programs`
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `programs`;
CREATE TABLE `programs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Nama program (misal: Internship Program)',
  `slug` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'URL-friendly identifier (unique)',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT 'Deskripsi lengkap program',
  `requirements` text COLLATE utf8mb4_unicode_ci COMMENT 'Persyaratan mengikuti program',
  `image` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Path/URL gambar program',
  `registration_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'URL Google Form / link pendaftaran',
  `status` enum('active','inactive') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active' COMMENT 'Status tampil di publik',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_programs_slug` (`slug`),
  KEY `idx_programs_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Program khusus: Internship, Management Trainee, OJT, dll.';

-- Data untuk Tabel: `programs` (3 baris)
INSERT INTO `programs` (`id`, `title`, `slug`, `description`, `requirements`, `image`, `registration_url`, `status`, `created_at`, `updated_at`) VALUES (1, 'ISA Management Trainee Program 2026', 'management-trainee-2026', 'Program percepatan karir komprehensif selama 12 bulan yang dirancang untuk menyiapkan talenta-talenta muda berbakat menjadi pemimpin masa depan di PT. Intersis Sejahtera Abadi. Peserta akan rotasi ke berbagai divisi strategis dan dibimbing langsung oleh jajaran manajemen senior.', '1. Lulusan S1/S2 dari Universitas terkemuka (IPK min 3.25).\n2. Usia maksimal 25 tahun untuk S1 dan 27 tahun untuk S2.\n3. Berjiwa kepemimpinan kuat, aktif dalam organisasi kemahasiswaan.\n4. Bersedia rotasi ke seluruh cabang operational perusahaan.', '/uploads/programs/mt_2026.jpg', 'https://forms.gle/isaProgramMT2026', 'active', '2026-09-25 07:34:29', '2026-09-25 07:34:29');
INSERT INTO `programs` (`id`, `title`, `slug`, `description`, `requirements`, `image`, `registration_url`, `status`, `created_at`, `updated_at`) VALUES (2, 'ISA NextGen Internship Experience', 'nextgen-internship', 'Pengalaman magang intensif selama 3-6 bulan bagi mahasiswa aktif untuk terlibat langsung dalam pengerjaan proyek nyata perusahaan. Peserta magang mendapatkan uang saku kompetitif, sertifikat resmi, dan peluang direkrut menjadi karyawan tetap.', '1. Mahasiswa aktif minimal semester 5 atau 7 dari semua jurusan yang relevan.\n2. Bersedia magang secara full-time (Senin-Jumat).\n3. Memiliki motivasi belajar tinggi, proaktif, dan dapat bekerjasama dalam tim.', '/uploads/programs/internship.jpg', 'https://forms.gle/isaProgramIntern2026', 'active', '2026-09-25 07:34:29', '2026-09-25 07:34:29');
INSERT INTO `programs` (`id`, `title`, `slug`, `description`, `requirements`, `image`, `registration_url`, `status`, `created_at`, `updated_at`) VALUES (3, 'Automotive Technical OJT Program', 'automotive-technical-ojt', 'Program Pelatihan Kerja Lapangan (On the Job Training) khusus lulusan SMK/D3 Teknik Elektro, Otomotif, dan Mekatronika untuk menguasai instalasi dan perawatan sistem audio video otomotif canggih.', '1. Lulusan SMK/D3 jurusan Teknik Otomotif, Elektro, atau Mekatronika.\n2. Memahami dasar-dasar kelistrikan kendaraan.\n3. Teliti, disiplin, dan mengutamakan keselamatan kerja (K3).', '/uploads/programs/ojt_tech.jpg', 'https://forms.gle/isaProgramOJT2026', 'active', '2026-09-25 07:34:29', '2026-09-25 07:34:29');

-- -------------------------------------------------------------
-- Struktur Tabel: `rfq_inquiries`
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `rfq_inquiries`;
CREATE TABLE `rfq_inquiries` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `full_name` varchar(150) NOT NULL,
  `corporate_email` varchar(150) NOT NULL,
  `company_name` varchar(150) NOT NULL,
  `phone` varchar(50) NOT NULL,
  `inquiry_type` varchar(100) DEFAULT NULL,
  `volume` varchar(100) DEFAULT NULL,
  `message` text,
  `country_code` varchar(10) DEFAULT 'ID',
  `country_name` varchar(100) DEFAULT 'Indonesia',
  `ip_address` varchar(45) DEFAULT NULL,
  `status` varchar(50) NOT NULL DEFAULT 'new',
  `spam_score` int(11) NOT NULL DEFAULT '0',
  `spam_reason` varchar(255) DEFAULT NULL,
  `notes` text,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4;

-- Data untuk Tabel: `rfq_inquiries` (5 baris)
