-- -------------------------------------------------------------
-- Struktur Tabel: `site_settings`
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `site_settings`;
CREATE TABLE `site_settings` (
  `key_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `content_json` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `updated_by` int(11) DEFAULT NULL,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`key_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Data untuk Tabel: `site_settings` (12 baris)
INSERT INTO `site_settings` (`key_name`, `content_json`, `updated_by`, `updated_at`) VALUES ('about_certifications', '{"id":[{"code":"IATF 16949","title":"Manajemen Mutu Otomotif Global","issuer":"Automotive Quality Task Force","desc":"Standar kualitas manufaktur suku cadang dan sistem elektronik otomotif dunia.","image":""},{"code":"ISO 9001:2015","title":"Sistem Manajemen Mutu","issuer":"International Organization for Standardization","desc":"Jaminan konsistensi mutu proses perakitan dan kepuasan pelanggan internasional.","image":""},{"code":"ISO 14001:2015","title":"Sistem Manajemen Lingkungan","issuer":"International Organization for Standardization","desc":"Kepatuhan penuh terhadap standar ramah lingkungan dan pengurangan limbah.","image":""},{"code":"ANSI/ESD S20.20","title":"Program Perlindungan Elektrostatik","issuer":"ESD Association","desc":"Prosedur pencegahan kerusakan elektrostatik pada komponen mikro presisi.","image":""}],"en":[{"code":"IATF 16949","title":"Global Automotive Quality Management","issuer":"Automotive Quality Task Force","desc":"World standard for automotive electronic parts and system manufacturing.","image":""},{"code":"ISO 9001:2015","title":"Quality Management Systems","issuer":"International Organization for Standardization","desc":"Guarantee of consistent assembly quality and international customer satisfaction.","image":""},{"code":"ISO 14001:2015","title":"Environmental Management Systems","issuer":"International Organization for Standardization","desc":"Full compliance with environmental standards and sustainable waste reduction.","image":""},{"code":"ANSI/ESD S20.20","title":"Electrostatic Discharge Control","issuer":"ESD Association","desc":"Rigorous ESD protection procedures for sensitive micro-electronic assemblies.","image":""}]}', 3, '2026-10-14 04:24:40');
INSERT INTO `site_settings` (`key_name`, `content_json`, `updated_by`, `updated_at`) VALUES ('about_narrative', '{"id":{"title":"PT. Global Philsonic Technologies","p1":"PT. Global Philsonic Technologies (GPT) adalah manufaktur perakitan elektronik presisi tinggi dan solusi otomasi industri terdepan yang beroperasi di Kawasan Bebas Batam (Free Trade Zone). Dengan fasilitas seluas 10.000 mt berstandar IATF 16949, kami memproduksi modul elektronik otomotif, headunit QLED pintar, sistem prosesor audio DSP, perangkat sensor keselamatan berkendara, dan jig uji fungsional otomatis berkecepatan 80.000 CPH.","p2":"Berbekal sertifikasi ISO 9001:2015 dan IATF 16949, kami menjalin kemitraan erat dengan klien Tier-1 internasional untuk memberikan efisiensi biaya, reliabilitas tanpa cela, dan kepatuhan standar industri otomotif global.","ftzTitle":"Keunggulan Strategis Batam Free Trade Zone (FTZ)","ftzPoints":[{"title":"0% Bea Masuk & Pajak Impor","desc":"Bebas bea masuk bahan baku komponen elektronik dan mesin manufaktur canggih."},{"title":"45 Menit Pengiriman ke Singapura","desc":"Akses logistik kapal laut harian langsung ke pelabuhan transshipment internasional Singapura."},{"title":"Sertifikasi Asal Barang (COO Indonesia)","desc":"Memenuhi persyaratan aturan asal barang internasional untuk kemudahan ekspor ke Amerika Serikat dan Uni Eropa."}]},"en":{"title":"PT. Global Philsonic Technologies","p1":"PT. Global Philsonic Technologies (GPT) is a leading manufacturer of high-precision electronic assembly and industrial automation solutions operating in the Batam Free Zone (Free Trade Zone). With a 10,000 mt facility with IATF 16949 standards, we produce automotive electronic modules, smart QLED headunits, DSP audio processor systems, driving safety sensor devices and automatic functional test jigs at 80,000 CPH.","p2":"Armed with ISO 9001:2015 and IATF 16949 certification, we partner closely with international Tier-1 clients to provide cost efficiency, flawless reliability and global automotive industry standards compliance.","ftzTitle":"Strategic Advantages of Batam Free Trade Zone (FTZ)","ftzPoints":[{"title":"0% Import Duty & Import Tax","desc":"Duty-free import of raw materials for electronic components and advanced manufacturing machines."},{"title":"45 Minutes Delivery to Singapore","desc":"Daily shipping logistics access directly to Singapore\'s international transshipment port."},{"title":"Certification of Origin of Goods (COO Indonesia)","desc":"Meets the requirements of international rules of origin for easy export to the United States and the European Union."}]}}', 1, '2026-10-12 03:45:21');
INSERT INTO `site_settings` (`key_name`, `content_json`, `updated_by`, `updated_at`) VALUES ('about_timeline', '{"id":[{"year":"2014","title":"Pendirian Pabrik di Batam FTZ","desc":"Memulai operasi perakitan audio elektronik presisi di Batam Free Trade Zone.","image":"/uploads/about/Screenshot_2026_09_01_144317_1791950068537-622247326.png"},{"year":"2017","title":"Sertifikasi Mutu ISO 9001","desc":"Mencapai sertifikasi sistem manajemen mutu internasional untuk manufaktur kontrak.","image":""},{"year":"2020","title":"Ekspansi Lini SMT 80.000 CPH","desc":"Penambahan mesin penempatan SMT kecepatan tinggi dan cleanroom Class 100K.","image":""},{"year":"2023","title":"Kepatuhan Otomotif IATF 16949","desc":"Resmi menjadi mitra manufaktur Tier-1 untuk perangkat kokpit dan headunit cerdas.","image":""},{"year":"2026","title":"Transformasi Industri 4.0 & Otomasi","desc":"Integrasi mesin jig uji otomatis dengan pelacakan MES berbasis cloud dan AI inspect.","image":""}],"en":[{"year":"2014","title":"Factory Establishment in Batam FTZ","desc":"Commenced precision audio assembly operations in Batam Free Trade Zone.","image":"/uploads/about/Screenshot_2026_09_01_144317_1791950068537-622247326.png"},{"year":"2017","title":"ISO 9001 Quality Certification","desc":"Achieved international quality management certification for contract manufacturing.","image":""},{"year":"2020","title":"80,000 CPH SMT Line Expansion","desc":"Added high-speed chip mounter lines and expanded Class 100K cleanroom floor.","image":""},{"year":"2023","title":"IATF 16949 Automotive Compliance","desc":"Certified as Tier-1 automotive manufacturing partner for smart cockpit systems.","image":""},{"year":"2026","title":"Industry 4.0 & Automation Integration","desc":"Integrated automated test jigs with cloud MES tracking and automated optical AI.","image":""}]}', 3, '2026-10-14 03:54:40');
INSERT INTO `site_settings` (`key_name`, `content_json`, `updated_by`, `updated_at`) VALUES ('about_vision_mission', '{"id":{"vision":"Menjadi mitra manufaktur Tier-1 elektronik otomotif dan rekayasa otomasi terpercaya di Asia Tenggara dengan standar mutu nol-cacat (Zero-Defect) serta efisiensi logistik bebas bea global.","mission":"Menghasilkan perakitan SMT presisi tinggi dengan toleransi mikron sesuai standar otomotif internasional IATF 16949.\\nMemberikan layanan OEM/ODM terintegrasi mulai dari DFM, prototyping kilat, hingga produksi massal dan box-build turnkey.\\nMengembangkan solusi rekayasa otomasi dan mesin jig uji pintar untuk memaksimalkan yield industri 4.0.\\n"},"en":{"vision":"Become a trusted Tier-1 manufacturing partner for automotive electronics and automation engineering in Southeast Asia with zero-defect quality standards and global duty-free logistics efficiency.","mission":"Produces high precision SMT assemblies with micron tolerances to international automotive standard IATF 16949.\\nProviding integrated OEM/ODM services from DFM, flash prototyping, to mass production and turnkey box-build.\\nDevelop automation engineering solutions and smart test jig machines to maximize industry 4.0 yields."}}', 1, '2026-10-12 03:44:35');
INSERT INTO `site_settings` (`key_name`, `content_json`, `updated_by`, `updated_at`) VALUES ('email_smtp_settings', '{"enabled":true,"smtp_host":"","smtp_port":587,"smtp_secure":false,"smtp_user":"","smtp_pass":"","sender_name":"PT. Global Philsonic Technologies","sender_email":"noreply@globalphilsonic.com","notify_emails":"sales@globalphilsonic.com","auto_reply_enabled":true}', NULL, '2026-10-12 04:51:30');
INSERT INTO `site_settings` (`key_name`, `content_json`, `updated_by`, `updated_at`) VALUES ('home_cta', '{\n  "id": {\n    "title": "Siap Mewujudkan Proyek Elektronik Otomotif Anda?",\n    "subtitle": "Diskusikan kebutuhan perakitan SMT, manufaktur OEM/ODM, atau integrasi otomasi pabrik dengan tim rekayasa GPT Batam.",\n    "buttonText": "Kirim Permintaan Penawaran (RFQ)",\n    "buttonLink": "/contact"\n  },\n  "en": {\n    "title": "Ready to Accelerate Your Automotive Electronics Project?",\n    "subtitle": "Consult your high-speed SMT assembly, OEM/ODM box-build, or factory automation integration with GPT Batam engineering team.",\n    "buttonText": "Request an Engineering Quote (RFQ)",\n    "buttonLink": "/contact"\n  }\n}', 1, '2026-10-01 03:22:55');
INSERT INTO `site_settings` (`key_name`, `content_json`, `updated_by`, `updated_at`) VALUES ('home_hero', '{"id":{"slides":[{"title":"Presisi Manufaktur Elektronik Otomotif Batam FTZ","subtitle":"Perakitan SMT berkecepatan 80.000 CPH, jaminan mutu IATF 16949, dan keunggulan logistik 0% tarif ke seluruh dunia.","actionText":"Konsultasi Engineering RFQ","actionLink":"/contact"},{"title":"Solusi Cerdas Headunit, Audio DSP & Otomasi Batam","subtitle":"Fasilitas cleanroom Class 100K terintegrasi di Batam Free Trade Zone - mitra Tier-1 perakitan OEM/ODM global.","actionText":"Lihat Produk & Spesifikasi","actionLink":"/products"}],"keywords":["Elektronik Otomotif","Perakitan SMT Presisi","Otomasi Industri","Partner OEM / ODM"]},"en":{"slides":[{"title":"Precision Automotive Electronics Manufacturing Batam FTZ","subtitle":"High-speed 80,000 CPH SMT placement, IATF 16949 quality assurance, and 0% duty logistics worldwide.","actionText":"Engineering RFQ Consultation","actionLink":"/contact"},{"title":"Smart Automotive Headunits, DSP Audio & Automation Batam","subtitle":"Integrated Class 100K cleanroom facility in Batam Free Trade Zone , trusted global Tier-1 OEM/ODM partner.","actionText":"Explore Products & Specs","actionLink":"/products"}],"keywords":["Automotive Electronics","Precision SMT Assembly","Industrial Automation","OEM / ODM Partner"]}}', 1, '2026-10-05 02:30:26');
INSERT INTO `site_settings` (`key_name`, `content_json`, `updated_by`, `updated_at`) VALUES ('home_stats', '{\n  "id": {\n    "experience": {\n      "value": 10,\n      "suffix": "+",\n      "label": "Tahun Pengalaman",\n      "sublabel": "Manufaktur Presisi Batam"\n    },\n    "capacity": {\n      "value": 80,\n      "suffix": "K CPH",\n      "label": "Kapasitas Penempatan SMT",\n      "sublabel": "Lini Berkecepatan Tinggi"\n    },\n    "area": {\n      "value": 10000,\n      "suffix": "m²",\n      "label": "Luas Area Pabrik",\n      "sublabel": "Fasilitas Cleanroom Terkontrol"\n    },\n    "yieldRate": {\n      "value": 99.8,\n      "suffix": "%",\n      "label": "Tingkat Yield Lolos Mutu",\n      "sublabel": "Standar Nol-Cacat Otomotif"\n    }\n  },\n  "en": {\n    "experience": {\n      "value": 10,\n      "suffix": "+",\n      "label": "Years of Experience",\n      "sublabel": "Precision Manufacturing Batam"\n    },\n    "capacity": {\n      "value": 80,\n      "suffix": "K CPH",\n      "label": "SMT Placement Capacity",\n      "sublabel": "High-Speed Dual-Beam Line"\n    },\n    "area": {\n      "value": 10000,\n      "suffix": "m²",\n      "label": "Factory Floor Area",\n      "sublabel": "Controlled Cleanroom Facility"\n    },\n    "yieldRate": {\n      "value": 99.8,\n      "suffix": "%",\n      "label": "Quality First-Pass Yield",\n      "sublabel": "Automotive Zero-Defect Standard"\n    }\n  }\n}', 1, '2026-10-01 03:22:55');
INSERT INTO `site_settings` (`key_name`, `content_json`, `updated_by`, `updated_at`) VALUES ('products_categories', '{\n    "id": [\n      {\n        "key": "headunit",\n        "name": "Headunit / Infotainment",\n        "desc": "Solusi headunit pintar layar sentuh QLED otomotif, konektivitas Apple CarPlay & Android Auto tanpa kabel, serta integrasi bus data CAN-Bus kendaraan."\n      },\n      {\n        "key": "audio",\n        "name": "Audio DSP & Amplifier",\n        "desc": "Digital Signal Processor (DSP) resolusi tinggi dan amplifier multi-kanal performa tinggi dengan kontrol akustik presisi 32-bit DAC."\n      },\n      {\n        "key": "dashcam",\n        "name": "Dashcam & ADAS Safety",\n        "desc": "Kamera pengawas berkendara sensor Sony STARVIS 2 4K UHD, radar sensor Blind-Spot 77GHz, dan modul keselamatan aktif ADAS."\n      },\n      {\n        "key": "automation",\n        "name": "Automation & Test Jigs",\n        "desc": "Mesin jig uji otomatis multi-stasiun ICT & FCT terintegrasi PLC, serta bangku pengujian kontinuitas wire harness 128-pin."\n      },\n      {\n        "key": "ems",\n        "name": "EMS / Contract Manufacturing",\n        "desc": "Layanan manufaktur kontrak elektronik (EMS) lini SMT berkecepatan 80.000 CPH, inspeksi 3D SPI/AOI, pelapisan konformal, hingga perakitan box-build."\n      }\n    ],\n    "en": [\n      {\n        "key": "headunit",\n        "name": "Headunit / Infotainment",\n        "desc": "Smart automotive QLED touchscreen headunit solutions, wireless Apple CarPlay & Android Auto connectivity, and in-vehicle CAN-Bus telemetry integration."\n      },\n      {\n        "key": "audio",\n        "name": "Audio DSP & Amplifier",\n        "desc": "High-resolution Digital Signal Processors (DSP) and high-performance multi-channel amplifiers featuring 32-bit DAC precision acoustic control."\n      },\n      {\n        "key": "dashcam",\n        "name": "Dashcam & ADAS Safety",\n        "desc": "Sony STARVIS 2 4K UHD driving dashcams, 77GHz millimeter-wave blind-spot radar sensors, and active ADAS safety modules."\n      },\n      {\n        "key": "automation",\n        "name": "Automation & Test Jigs",\n        "desc": "PLC-integrated automated multi-station ICT & FCT test fixtures and 128-point automotive wire harness continuity test benches."\n      },\n      {\n        "key": "ems",\n        "name": "EMS / Contract Manufacturing",\n        "desc": "Turnkey electronics contract manufacturing (EMS) featuring 80,000 CPH high-speed SMT lines, 3D SPI/AOI inspection, conformal coating, and full box-build assembly."\n      }\n    ]\n  }', NULL, '2026-10-01 06:46:16');
INSERT INTO `site_settings` (`key_name`, `content_json`, `updated_by`, `updated_at`) VALUES ('products_header', '{\n    "id": {\n      "title": "Solusi Manufaktur Elektronik Otomotif & Otomasi Presisi",\n      "subtitle": "Katalog resmi produk siap OEM/ODM standar Tier-1, prosesor audio DSP, perangkat keselamatan berkendara, mesin jig uji otomatis, dan layanan kontrak perakitan SMT berkecepatan tinggi di Kawasan Bebas Batam (FTZ).",\n      "chips": [\n        { "value": "12+ Model", "label": "SKU Siap Produksi", "sub": "Turnkey OEM / ODM" },\n        { "value": "80.000 CPH", "label": "Kecepatan Lini SMT", "sub": "Yamaha & Panasonic Lines" },\n        { "value": "IATF 16949", "label": "Standar Mutu Nol Cacat", "sub": "& ISO 9001:2015" },\n        { "value": "45 Menit", "label": "Logistik Bebas Pajak", "sub": "Batam FTZ ke Singapura" }\n      ]\n    },\n    "en": {\n      "title": "Automotive Electronics & Precision Manufacturing Catalog",\n      "subtitle": "Official engineering catalog of Tier-1 standard OEM/ODM products, DSP audio processors, in-vehicle safety sensors, automated test fixtures, and high-speed turnkey SMT assembly at Batam Free Trade Zone.",\n      "chips": [\n        { "value": "12+ Models", "label": "Production-Ready SKUs", "sub": "Turnkey OEM / ODM" },\n        { "value": "80,000 CPH", "label": "SMT Line Capacity", "sub": "Yamaha & Panasonic Lines" },\n        { "value": "IATF 16949", "label": "Zero-Defect Standard", "sub": "& ISO 9001:2015" },\n        { "value": "45 Minutes", "label": "Duty-Free Logistics", "sub": "Batam FTZ to Singapore" }\n      ]\n    }\n  }', NULL, '2026-10-01 06:46:16');
INSERT INTO `site_settings` (`key_name`, `content_json`, `updated_by`, `updated_at`) VALUES ('products_rfq', '{\n    "id": {\n      "rfqTitle": "Membutuhkan Kustomisasi Khusus atau Tooling Baru?",\n      "rfqSubtitle": "Tim R&D dan engineering kami di Batam FTZ siap berkolaborasi untuk perancangan skematik PCB, penyesuaian firmware CAN-Bus, hingga perakitan turnkey box-build standar ekspor global.",\n      "rfqButton": "Konsultasi Cepat via WhatsApp B2B",\n      "workflowTitle": "Dari Desain Konsep Hingga Produksi Massal (OEM / ODM Journey)",\n      "workflowSubtitle": "Metodologi rekayasa terstruktur kami menjamin kualitas bebas cacat (Zero-Defect), kepatuhan regulasi otomotif, dan efisiensi biaya manufaktur.",\n      "steps": [\n        {\n          "step": "01",\n          "title": "Analisis RFQ & Review BOM",\n          "desc": "Evaluasi mendalam spesifikasi teknis, ketersediaan komponen, dan kalkulasi penawaran biaya resmi dalam 24-48 jam."\n        },\n        {\n          "step": "02",\n          "title": "Rekayasa DFM & Rapid Prototyping",\n          "desc": "Optimalisasi layout Design-for-Manufacturing (DFM) untuk menjamin yield SMT maksimal dan pembuatan sampel uji fungsional."\n        },\n        {\n          "step": "03",\n          "title": "Tooling, Stensil & Pilot Run",\n          "desc": "Fabrikasi stensil laser elektropolis serta pengujian perakitan batch awal terkontrol untuk memvalidasi toleransi mesin."\n        },\n        {\n          "step": "04",\n          "title": "Validasi Kualitas 100% (SPI, AOI, ICT)",\n          "desc": "Inspeksi pasta solder 3D, inspeksi optik otomatis AOI, validasi jalur kelistrikan ICT, dan uji ketahanan termal ekstrem."\n        },\n        {\n          "step": "05",\n          "title": "Produksi Massal & Ekspor FTZ",\n          "desc": "Perakitan massal berkecepatan 80.000 CPH, integrasi serialisasi barcode MES, dan pengiriman kilat 45 menit ke pelabuhan Singapura."\n        }\n      ]\n    },\n    "en": {\n      "rfqTitle": "Need Custom Engineering or New Product Tooling?",\n      "rfqSubtitle": "Our engineering & R&D team at Batam FTZ is ready to collaborate on schematic design, CAN-Bus firmware customization, and turnkey box-build assembly for global export.",\n      "rfqButton": "Direct B2B WhatsApp Consultation",\n      "workflowTitle": "From Concept Design to Mass Production (OEM / ODM Journey)",\n      "workflowSubtitle": "Our structured engineering methodology guarantees zero-defect quality, automotive regulatory compliance, and maximum cost efficiency.",\n      "steps": [\n        {\n          "step": "01",\n          "title": "RFQ & BOM Review",\n          "desc": "Technical specification review, component sourcing validation, and cost quotation within 24-48 business hours."\n        },\n        {\n          "step": "02",\n          "title": "DFM Engineering & Prototyping",\n          "desc": "Design-for-Manufacturing optimization ensuring optimal SMT placement yields and functional engineering prototypes."\n        },\n        {\n          "step": "03",\n          "title": "Tooling, Stencils & Pilot Run",\n          "desc": "Electro-polished laser stencil fabrication and controlled pilot production batches to qualify machinery tolerances."\n        },\n        {\n          "step": "04",\n          "title": "100% Quality Validation (SPI, AOI, ICT)",\n          "desc": "3D solder paste inspection, automated optical inspection, in-circuit testing, and dynamic thermal burn-in validation."\n        },\n        {\n          "step": "05",\n          "title": "Mass Assembly & FTZ Logistics",\n          "desc": "High-speed 80K CPH assembly, real-time MES barcode serialization, and 45-minute express transit to Singapore seaport."\n        }\n      ]\n    }\n  }', NULL, '2026-10-01 06:46:16');
INSERT INTO `site_settings` (`key_name`, `content_json`, `updated_by`, `updated_at`) VALUES ('site_branding', '{"site_name":"PT. Global Philsonic Technologies","tagline":"Automotive Electronics & Industrial Automation","logo_url":"/images/logo_company.jpg","favicon_url":"/uploads/branding/favicon_1791777929111-71113955.png","meta_title_separator":"|","title_format":"per_page"}', 1, '2026-10-12 04:05:37');

-- -------------------------------------------------------------
-- Struktur Tabel: `users`
-- -------------------------------------------------------------
DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Nama lengkap pengguna',
  `username` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Username unik untuk login',
  `email` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Email unik untuk login',
  `password` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Password terenkripsi (bcrypt)',
  `role` enum('administrator','hrd','staff') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'staff' COMMENT 'Hak akses: administrator > hrd > staff',
  `status` enum('active','inactive') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'active' COMMENT 'Status akun pengguna',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_users_username` (`username`),
  UNIQUE KEY `uq_users_email` (`email`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Akun internal HRD: Administrator, HRD, Staff HRD';

-- Data untuk Tabel: `users` (3 baris)
